validator:
function validate(input) {
  const [{ Customers = [] }] = input;
  const seen = new Set();
  for (const row of Customers) {
    if (row.some((v) => v === null)) return 'Customers rows may not contain null.';
    const key = `${row[0]}|${row[1]}`;
    if (seen.has(key)) return `Customer ${row[0]} has two rows for year ${row[1]}.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const years = small ? [2019, 2020, 2021, 2022] : [2016, 2017, 2018, 2019, 2020, 2021, 2022];
  const customers = small ? 4 : 400;
  const target = small ? pick(9) : 2000;
  const seen = new Set(), Customers = [];
  for (let tries = 0; Customers.length < target && tries < target * 10; tries++) {
    const id = 1 + pick(customers);
    // 2021 is drawn more often so that the filter has something to decide.
    const year = rand() < 0.4 ? 2021 : years[pick(years.length)];
    if (seen.has(`${id}|${year}`)) continue;
    seen.add(`${id}|${year}`);
    const revenue = small ? [-50, -1, 0, 1, 30, 70][pick(6)] : pick(401) - 200;
    Customers.push([id, year, revenue]);
  }
  return [{ Customers }];
}
